@import "tailwindcss";

:root {
  --ink:    #15120E;
  --sand:   #F6F4F0;
  --glass:  rgba(250, 248, 245, 0.68);
  --warm:   #C09060;
}

@theme inline {
  --color-background: var(--sand);
  --color-foreground: var(--ink);
  --font-sans: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, 'Courier New', monospace;
}

html {
  color-scheme: light;
  background: var(--sand);
}

body {
  min-height: 100vh;
  background: #F6F4F0;
  color: var(--ink);
  font-family: var(--font-sans);
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

* { box-sizing: border-box; }

::selection {
  background: rgba(192, 144, 96, 0.18);
  color: var(--ink);
}

::-webkit-scrollbar { width: 0; }

/* ── Glass surface ────────────────────────────────────────────────── */
.glass-surface {
  background: rgba(252, 250, 247, 0.72);
  backdrop-filter: blur(28px) saturate(160%);
  -webkit-backdrop-filter: blur(28px) saturate(160%);
  border: 1px solid rgba(255, 255, 255, 0.88);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.92),
    0 24px 56px rgba(21, 18, 14, 0.055),
    0 6px 16px rgba(21, 18, 14, 0.032);
}

.glass-surface-subtle {
  background: rgba(255, 255, 255, 0.52);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.75);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    0 12px 32px rgba(21, 18, 14, 0.04);
}

/* ── Graph atmosphere ─────────────────────────────────────────────── */
.graph-fog {
  background: radial-gradient(
    ellipse at 50% 50%,
    rgba(255, 255, 255, 0.55) 0%,
    rgba(246, 244, 240, 0.18) 45%,
    transparent 68%
  );
}

/* ── Ambient pulse ────────────────────────────────────────────────── */
@keyframes breathe {
  0%, 100% { opacity: 0.5; transform: scale(1); }
  50%       { opacity: 0.75; transform: scale(1.04); }
}

@keyframes drift {
  0%, 100% { transform: translateY(0); }
  50%       { transform: translateY(-14px); }
}

@keyframes ripple {
  0%   { transform: scale(1);   opacity: 0.18; }
  100% { transform: scale(3.5); opacity: 0; }
}

.orb-breathe { animation: breathe 18s ease-in-out infinite; }
.orb-drift   { animation: drift   22s ease-in-out infinite; }

