                      {[32, 52, 78, 110].map((size, i) => (
                        <motion.div key={size}
                          className="absolute rounded-full border border-[#13100D]/7"
                          style={{ width: size, height: size }}
                          animate={{ scale: [1, 1.45, 1], opacity: [0.07, 0, 0.07] }}
                          transition={{
                            duration: 4.5 + i * 0.6,
                            delay: i * 1.1,
                            repeat: Infinity, ease: "easeOut",
